import heapq

def match(orders):
    trades = []
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> {'side':, 'price':, 'qty':, 'seq':, 'active': bool}
    seq_counter = 0

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book and book[oid]['active']:
                book[oid]['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        seq = seq_counter
        seq_counter += 1

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
            while remaining > 0 and opp_heap:
                top = opp_heap[0]
                top_price, top_seq, top_id = top
                if top_id not in book or not book[top_id]['active']:
                    heapq.heappop(opp_heap)
                    continue
                if price is not None and top_price > price:
                    break
                heapq.heappop(opp_heap)
                resting = book[top_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([oid, top_id, top_price, trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] > 0:
                    heapq.heappush(opp_heap, (top_price, top_seq, top_id))
                else:
                    resting['active'] = False
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
                heapq.heappush(buy_heap, (-price, seq, oid))
        else:  # sell
            opp_heap = buy_heap
            while remaining > 0 and opp_heap:
                top = opp_heap[0]
                neg_price, top_seq, top_id = top
                top_price = -neg_price
                if top_id not in book or not book[top_id]['active']:
                    heapq.heappop(opp_heap)
                    continue
                if price is not None and top_price < price:
                    break
                heapq.heappop(opp_heap)
                resting = book[top_id]
                trade_qty = min(remaining, resting['qty'])
                trades.append([top_id, oid, top_price, trade_qty])
                remaining -= trade_qty
                resting['qty'] -= trade_qty
                if resting['qty'] > 0:
                    heapq.heappush(opp_heap, (neg_price, top_seq, top_id))
                else:
                    resting['active'] = False
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq, 'active': True}
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

